public class GameMain extends Game {
    public GameObject player;
    public int kills;
    public int totalEnemies;

    @Override public void onCreate() { build(); }

    @Override public void onUpdate(double delta) {
        if (input.isKeyPressed(Keys.R)) build();
    }

    private void block(double x, double y) {
        GameObject stone = createObject("Stone").setPosition(x, y);
        stone.addComponent(new Sprite(Assets.STONE, 32, 32));
        stone.addComponent(new Collider2D(32, 32));
    }

    private void spikes(double x, double y) {
        GameObject trap = createObject("Spikes").setPosition(x, y);
        trap.addComponent(new Sprite(Assets.STAKE, 32, 24));
        trap.addComponent(new Collider2D(28, 12).asTrigger());
        trap.addComponent(new SpikeHazard());
    }

    private void heart(double x, double y) {
        GameObject heart = createObject("Heart").setPosition(x, y);
        heart.addComponent(new Sprite(Assets.HEART, 24, 24));
        heart.addComponent(new CircleCollider2D(10).asTrigger());
        heart.addComponent(new HeartPickup());
    }

    private void enemy(Assets sprite, double x, double y, double hp, double speed) {
        totalEnemies++;
        GameObject e = createObject("Enemy").setPosition(x, y);
        e.addComponent(new Sprite(sprite, 32, 32));
        Collider2D body = e.addComponent(new Collider2D(22, 26));
        body.layer = Layers.ENEMY;
        e.addComponent(new PlatformerCharacterController2D());
        e.addComponent(new Health(hp));
        e.addComponent(new EnemyBrain(speed, x - 80, x + 80));
    }

    private void build() {
        for (GameObject o : new java.util.ArrayList<>(getObjects())) o.destroy();
        kills = 0; totalEnemies = 0;
        setWorldBounds(0, 0, 1280, 480);

        GameObject ground = createObject("Ground");
        TileMap map = ground.addComponent(new TileMap(Assets.STONE, 32));
        for (int c = 0; c < 40; c++)
            for (int r = 12; r < 15; r++)
                map.setTile(c, r, Assets.STONE);

        GameObject floor = createObject("Floor").setPosition(640, 416);
        floor.addComponent(new Collider2D(1280, 64));

        for (int i = 0; i < 3; i++) block(288 + i * 32, 336);
        for (int i = 0; i < 4; i++) block(608 + i * 32, 288);
        for (int i = 0; i < 3; i++) block(928 + i * 32, 336);
        block(1184, 240);

        spikes(480, 372); spikes(840, 372);
        heart(640, 248); heart(1184, 200);

        enemy(Assets.SKELETON, 400, 340, 2, 50);
        enemy(Assets.ZOMBIE, 700, 340, 3, 35);
        enemy(Assets.WOLF, 1000, 340, 2, 90);

        player = createObject("Player").setPosition(60, 330);
        player.addComponent(new Sprite(Assets.ROGUE, 32, 32));
        Collider2D body = player.addComponent(new Collider2D(20, 28));
        body.layer = Layers.PLAYER;
        player.addComponent(new PlatformerCharacterController2D());
        player.addComponent(new Health(5));
        player.addComponent(new PlayerControls());

        GameObject camera = createObject("Camera");
        camera.addComponent(new Camera2D()).follow(player);
    }

    @Override public void onDrawUI() {
        Health hp = player == null || player.destroyed ? null : player.getComponent(Health.class);
        if (hp != null) {
            canvas.drawRect(48, 18, 92, 12, "#3a2030");
            if (hp.current > 0) canvas.drawRect(48, 18, 92 * hp.current / hp.max, 12, "#e05050");
            canvas.drawText("HP", 96, 18, 12, "#ffffff", "left", "middle");
        }
        canvas.drawText("Zabici: " + kills + "/" + totalEnemies + "   X atak  SHIFT unik  R restart", 320, 18, 16, "#d0a0ff", "center", "middle");
        if (kills >= totalEnemies && totalEnemies > 0) canvas.drawText("KRYPTA OCZYSZCZONA!", 320, 60, 24, "#7cfc90", "center", "middle");
        if (hp != null && hp.dead) canvas.drawText("ZGINIONO — wcisnij R", 320, 60, 24, "#ff6060", "center", "middle");
    }
}

