public class Health extends Component {
    public double max, current, invulnerable;
    public boolean dead;
    public Health(double max) { this.max = max; this.current = max; }
    @Override public void onUpdate(double delta) {
        if (invulnerable > 0) invulnerable -= delta;
    }
    public boolean damage(double amount) {
        if (dead || invulnerable > 0 || amount <= 0) return false;
        current = Math.max(0, current - amount);
        if (current == 0) { dead = true; gameObject.destroy(); }
        return true;
    }
    public void heal(double amount) {
        if (!dead) current = Math.min(max, current + amount);
    }
}

