public class PlayerControls extends Component {
    public double dashTime;
    public double facing = 1;
    public double attackCooldown;

    @Override public void onUpdate(double delta) {
        PlatformerCharacterController2D body = requireComponent(PlatformerCharacterController2D.class);
        Health hp = getComponent(Health.class);
        if (hp.dead) { body.move(0, 0, 0); return; }
        double x = (getGame().input.isKeyDown(Keys.D) || getGame().input.isKeyDown(Keys.RIGHT) ? 1 : 0)
                 - (getGame().input.isKeyDown(Keys.A) || getGame().input.isKeyDown(Keys.LEFT) ? 1 : 0);
        if (x != 0) facing = x;
        if (attackCooldown > 0) attackCooldown -= delta;
        if (dashTime > 0) {
            dashTime -= delta;
            body.velocity.x = facing * 420;
        } else {
            body.walk(x);
            if (getGame().input.isKeyPressed(Keys.SHIFT)) {
                dashTime = 0.18;
                hp.invulnerable = 0.35;
            }
        }
        if ((getGame().input.isKeyPressed(Keys.SPACE) || getGame().input.isKeyPressed(Keys.W) || getGame().input.isKeyPressed(Keys.UP)) && body.isGrounded())
            body.jump();
        if (getGame().input.isKeyPressed(Keys.X) && attackCooldown <= 0) {
            attackCooldown = 0.35;
            slash();
        }
        if (transform.y > 470) { hp.damage(1); transform.x = 60; transform.y = 330; }
    }

    private void slash() {
        GameObject hit = getGame().createObject("Slash").setPosition(transform.x + facing * 26, transform.y - 4);
        hit.addComponent(new Sprite(Assets.SLASH, 32, 32));
        Collider2D area = hit.addComponent(new Collider2D(40, 24).asTrigger());
        area.mask = Layers.ENEMY;
        hit.addComponent(new Slash(1));
        getGame().audio.playNote("A4", 0.08, "sawtooth");
    }
}

