public class Slash extends Component {
    public double damage, remaining = 0.12;
    public Slash(double damage) { this.damage = damage; }
    @Override public void onUpdate(double delta) {
        remaining -= delta;
        if (remaining <= 0) gameObject.destroy();
    }
    @Override public void onTrigger(GameObject other) {
        Health hp = other.getComponent(Health.class);
        if (hp == null || !other.hasComponent(EnemyBrain.class)) return;
        if (hp.damage(damage)) {
            if (hp.dead) ((GameMain) getGame()).kills++;
            gameObject.destroy();
        }
    }
}

