public class EnemyBrain extends Component {
    public double speed, minX, maxX, dir = 1, touchCooldown;
    public EnemyBrain(double speed, double minX, double maxX) { this.speed = speed; this.minX = minX; this.maxX = maxX; }
    @Override public void onUpdate(double delta) {
        if (getComponent(Health.class).dead) return;
        if (touchCooldown > 0) touchCooldown -= delta;
        PlatformerCharacterController2D body = requireComponent(PlatformerCharacterController2D.class);
        GameObject player = ((GameMain) getGame()).player;
        double dx = player == null || player.destroyed ? 0 : player.transform.x - transform.x;
        if (Math.abs(dx) < 160) dir = dx > 0 ? 1 : -1;
        body.walk(dir);
        if (transform.x > maxX) dir = -1;
        if (transform.x < minX) dir = 1;
        Sprite sprite = getComponent(Sprite.class);
        if (sprite != null) sprite.flipX = dir < 0;
    }
    @Override public void onCollision(GameObject other) {
        if (!other.hasComponent(PlayerControls.class) || touchCooldown > 0) return;
        touchCooldown = 0.6;
        Health hp = other.getComponent(Health.class);
        if (hp != null && hp.damage(1)) {
            hp.invulnerable = 0.6;
            CharacterController2D body = other.getComponent(CharacterController2D.class);
            if (body != null) body.velocity.x = transform.x < other.transform.x ? 220 : -220;
        }
    }
}

