public class HeartPickup extends Component {
    @Override public void onTrigger(GameObject other) {
        if (!other.hasComponent(PlayerControls.class)) return;
        Health hp = other.getComponent(Health.class);
        if (hp != null && hp.current < hp.max) {
            hp.heal(1);
            getGame().audio.playNote("C6", 0.15, "triangle");
            gameObject.destroy();
        }
    }
}
